        "ثالثًا: السلامة والخطوة الأولى. القاعدة الذهبية: افصل كابل USB عن اللوحة أولًا، واشتغل دائمًا واللوحة بلا كهرباء، فالتوصيل أثناء التشغيل قد يسبب لمسًا خاطئًا يضر اللوحة. الخطوة الأولى: صل إحدى رجلي المقاومة بالمنفذ 13 في اللوحة، ورجلها الأخرى في ثقب ضمن مجموعة حرة في لوحة التجارب، فتقف المقاومة جسرًا بين اللوحة ولوحة التجارب، وهذا مقصود.",
        "رابعًا: إكمال الدائرة. الخطوة الثانية: ضع الرجل الطويلة الموجبة للصمام في ثقب من نفس مجموعة المقاومة على لوحة التجارب حتى يلتقي الطرفان كهربائيًا. الخطوة الثالثة: ضع الرجل القصيرة السالبة بحيث تصل إلى خط الأرضي الجانبي، مباشرة أو بسلك توصيل قصير. الخطوة الرابعة: صل خط الأرضي الجانبي بمنفذ GND في اللوحة. بهذا اكتمل مسار الدائرة: من المنفذ 13 إلى المقاومة إلى الصمام إلى الأرضي.",
        "خامسًا: التشغيل. أعد توصيل كابل USB وارفع نفس برنامج الوميض دون أي تغيير: pinMode للمنفذ 13، و digitalWrite بـ HIGH و LOW مع delay(1000). ستلاحظ أمرًا جميلًا: المنفذ 13 يقود الآن صمامين معًا، المدمج داخل اللوحة والخارجي الذي وصلته بيدك، فيومضان في اللحظة نفسها تمامًا. لقد بنيت أول دائرة حقيقية في حياتك.",
