        "ثالثًا: التوصيل — ننقل السلك إلى المنفذ 9. دائرتنا هي دائرة الصمام الخارجي نفسها، والتغيير الوحيد: افصل اللوحة عن الطاقة أولًا، ثم انقل سلك الإشارة من المنفذ 13 إلى المنفذ 9، لأن analogWrite تحتاج منفذًا يدعم PWM. هذه المنافذ تحمل علامة موجة صغيرة ~ بجوار رقمها على لوحة Uno، وهي: 3 و 5 و 6 و 9 و 10 و 11. وتبقى مقاومة 220Ω وقطبية الصمام كما هي تمامًا، ويجب أن يتغير رقم المنفذ في الكود أيضًا، فلا فائدة من نقل السلك وحده.",
        "رابعًا: قيم analogWrite. نكتب فيها رقم المنفذ ثم قيمة السطوع، والقيم محصورة بين 0 و 255 فقط: صفر يعني انطفاءً تامًا، و 255 تعني أقصى سطوع، ونحو 64 سطوع خفيف قريب من الربع، ونحو 128 سطوع متوسط قريب من النصف. كلما كبرت القيمة زاد زمن التشغيل في كل نبضة فزاد السطوع الذي تراه العين. جرّب المنزلق في التجربة التفاعلية ولاحظ نسبة دورة العمل والجهد التقريبي لكل قيمة.",
