        "أولًا: التوصيلة، ونعمل دائمًا وكابل USB مفصول. نوصل الرجل الطويلة لكل صمام بسلك إلى منفذه: الأول إلى المنفذ 8، والثاني إلى 9، والثالث إلى 10. ثم نوصل الرجل القصيرة لكل صمام إلى مقاومته الخاصة 220Ω — مقاومة لكل صمام، لا مقاومة واحدة للجميع — ومنها إلى خط أرضي مشترك على لوحة التجارب، ثم نوصل هذا الخط بسلك واحد إلى منفذ GND في اللوحة. راجع القطبية والأرضي المشترك قبل وصل الكابل.",
