        "رابعًا: كود الإضاءة المتتابعة. داخل setup حلقة for قصيرة تجهّز المنافذ الثلاثة دفعة واحدة بدل pinMode ثلاث مرات: تنفّذ pinMode(i, OUTPUT) عند 8 ثم 9 ثم 10، وعندما يصير العداد 11 يصير الشرط غير صحيح فتتوقف الحلقة. وداخل loop حلقة for ثانية تصنع التتابع: تشعل الصمام الحالي، وتنتظر delay(300)، وتطفئه، ثم ينتقل العداد إلى المنفذ الموالي. وعند انتهاء الحلقة تعود loop من البداية فيجري الضوء من صمام إلى صمام بلا توقف. جرّب المحاكاة أسفل الصفحة بطورَي for و while ولاحظ العداد.",
