        "في المستوى الأول جعلنا اللوحة تنفّذ أوامرنا وتشعل الصمامات، لكنها كانت تعمل في صمت: لا نرى إلا النتيجة الأخيرة، ولا نعرف ماذا يجري داخلها أثناء العمل. تخيّل لوحتك غرفة مغلقة الباب وبرنامجك يعمل داخلها بهدوء؛ الشاشة التسلسلية Serial Monitor هي نافذة زجاجية صغيرة في باب هذه الغرفة: تنظر منها فترى القراءات والرسائل لحظة بلحظة. وبدل التخمين عند حدوث مشكلة، تطبع قيمة هنا ورسالة هناك، فيخبرك البرنامج بنفسه أين وصل وأين الخطأ.",
