        "أولًا: الترانزستور 2N2222 وأرجله الثلاث. رجل القاعدة Base هي مدخل إشارة التحكم الصغيرة القادمة من المنفذ. ورجل المجمّع Collector هي باب التيار الكبير من جهة المحرك. ورجل الباعث Emitter هي المخرج نحو الأرضي GND. ولتمييز الأرجل عمليًّا: ضع الجهة المسطّحة من جسم الترانزستور أمامك والأرجل إلى أسفل، فيكون الترتيب من اليسار: الباعث ثم القاعدة ثم المجمّع. احفظ هذا الترتيب جيدًا، فتبديل رجلين فقط يجعل الدائرة صامتة تمامًا.",
