        "رابعًا: الكود على أجزاء كالمعتاد. في setup نفتح الشاشة التسلسلية بـ Serial.begin(9600) لنطبع رسائلنا، ونجعل المنافذ 2 و3 و4 مداخل INPUT لأنها تقرأ الأزرار، والمنفذ 8 مخرجًا OUTPUT لأنه يرسل الأوامر إلى الجرس؛ فالمداخل تستقبل قرارات أصابعك والمخرج واحد ينفّذ الصوت. وفي loop ثلاث كتل شرطية متشابهة، واحدة لكل زر: إذا كان المنفذ HIGH عزفنا بـ tone التردد المناسب وطبعنا بـ println رسالة باسم الزر والنغمة. ثم كتلة أخيرة صغيرة تصنع الفرق كله: إذا كانت المنافذ الثلاثة كلها LOW معًا نفّذنا noTone(8) فيسكت الجرس فورًا؛ وبدونها يبقى آخر صوت معلّقًا حتى بعد رفع أصابعك كلها.",
        "خامسًا: الاختبار والتحسين. ارفع البرنامج وافتح الشاشة التسلسلية، واختبر كل زر وحده: اضغط الأول واسمع دو وتأكد أن رسالته الصحيحة ظهرت، ثم كرر مع مي ثم صول. ولاحظ الصمت: ارفع إصبعك فيجب أن يسكت الجرس في اللحظة نفسها، فإن بقي الصوت فراجع كتلة noTone. وجرّب زرّين معًا وستلاحظ أن الجرس يعزف نغمة واحدة فقط، لأن صوتًا واحدًا يخرج في اللحظة الواحدة، وهذا طبيعي وليس عطلًا. وإن ظهرت نغمات وحدها دون ضغط فالسبب الغالب مدخل عائم، فراجع مقاومات السحب السفلي أولًا. أخطاء شائعة أيضًا: تبديل منافذ الأزرار بين التوصيل والكود، وعكس طرفَي الجرس، واختيار سرعة شاشة مختلفة عن 9600 فتتشوش الرسائل. وعند أي مشكلة اعمل بهدوء: زر واحد في كل مرة، التوصيل أولًا ثم الكود. ألف مبروك: جمعت قراءة الأزرار بالشروط وربطتها بتوليد النغمات والطباعة التسلسلية، وأنهيت المستوى الثاني: التحكم والقرارات."
