        "منافذ التحكم الستة من اللوحة إلى الدرايفر: ENA إلى المنفذ 9، وIN1 إلى 7، وIN2 إلى 6، وIN3 إلى 5، وIN4 إلى 4، وENB إلى 3. لاحظ أن منفذي التمكين 9 و3 هما منفذا PWM، لأن السرعة ستُضبط عليهما. في setup نهيئ المنافذ الستة كلها مخارج.",
