        "التوصيل على جانبين. جانب التحكم بثلاثة أسلاك فقط: طاقة وحدة الريلاي إلى 5V في اللوحة، وأرضيها إلى GND، وسلك إشارتها إلى المنفذ 7. جانب الحمل دائرة منفصلة تمامًا لا يلمس سلك منها اللوحة: موجب علبة البطاريات إلى الطرف COM، ومن الطرف NO إلى موجب الحمل — مروحة صغيرة 5V أو شريط صمام قوي — ثم سالب الحمل إلى سالب علبة البطاريات، فتكتمل الدائرة: بطاريات ثم ريلاي ثم حمل ثم بطاريات. الحمل يأخذ طاقته من بطارياته دائمًا، لا من اللوحة أبدًا.",
        "الكود بسيط بقدر الفكرة: المنفذ 7 مخرج في setup، وكتابة HIGH تفعّل الملف فتُغلق نقطة NO فتدور المروحة مع طقطقة، وكتابة LOW تفتح الدائرة فتتوقف. جرّب إيقاعًا بطيئًا بثلاث ثوانٍ تشغيلًا وثلاثًا إيقافًا وعدّ الطقطقات. والفكرة الأجمل أن يقرر حساس بدلًا منك: حسّاس يحسّ، والبرنامج يقرر، والريلاي ينفّذ — حرارة مرتفعة فتشتغل المروحة وحدها، دائمًا بجهد البطاريات المنخفض الآمن فقط.",
        "أخطاء شائعة: تبديل NO وNC فيعمل الحمل عكس الأمر تمامًا — راجع اسم كل طرف قبل تثبيت سلكه؛ وتوقّع صمت الريلاي، فالطقطقة طبيعية؛ وأخطرها تجاوز حدود الدرس نحو أحمال البيت، وهو ممنوع وخطير. لخّص بيدك بعد الدرس: ارسم دائرتي التحكم والحمل منفصلتين تمامًا وسمِّ الأطراف الثلاثة على رسمك."
