        "العناصر ودور كل عنصر: الهيكل بعجلتين خلفيتين وكرة دوّارة أمامية للتوازن وحرية الدوران، ومحركا DC مركّبة على كل واحد عجلته، ودرايفر L298N وهو الوسيط القوي بين اللوحة والمحركات لأن المحركات لا تتغذى من منفذ اللوحة أبدًا، وسيرفو يحمل حساس المسافة فيصيران رأسًا وعينًا، وعلبة بطاريات 4×AA مصدر طاقة المحركات، ولوحة Uno ولوحة تجارب صغيرة وأسلاك ملونة طويلة حتى لا تنشدّ مع دوران الرأس.",
        "خطوات التوصيل على مراحل: المرحلة الأولى الهيكل والمحركات والطاقة، والطاقة مفصولة قبل أي توصيل: المحرك الأول إلى مخرجي الدرايفر الأول والثاني، والثاني إلى الثالث والرابع، وموجب البطاريات إلى مدخل طاقة الدرايفر وسالبها إلى أرضيه، وأرضي الدرايفر إلى أرضي اللوحة فالأرضي مشترك بين الجميع، ونفحص باتجاهات العجلتين فقط. المرحلة الثانية السيرفو وحده: إشارته إلى المنفذ 9 ونختبر مسحه قبل تركيب الحساس فوقه. المرحلة الثالثة الحساس: لأن المنفذ 9 مشغول بالسيرفو ننقل الحساس إلى منفذين حرّين، فالزناد Trig إلى المنفذ 12 والصدى Echo إلى المنفذ 11، ونقارن قراءاته بمسطرة حقيقية. منافذ اتجاه الدرايفر: الأيسر 7 و6 والأيمن 5 و4، وقافزتا التمكين تبقيان مركّبتين فيعمل المحركان بكامل قوة البطاريات ونوجّه بالاتجاهات والأزمنة فقط.",
        "منطق الكود على ثلاثة أجزاء: الجزء الأول التعريفات ودالة قياس المسافة التي ترسل نبضة نظيفة وتقيس زمن الصدى بمهلة، فإذا لم يرجع صدى أعادت 999 أي طريق مفتوح، وإلا حوّلت الزمن إلى سنتيمترات، ومسافة الأمان SAFE هي 20 سم. الجزء الثاني دالة القيادة التي تستقبل اتجاه كل عجلة بلغة ثلاث قيم: 1 تقدم و-1 تراجع و0 توقف، وتترجمها إلى منافذ الدرايفر الأربعة، مع التهيئة في setup. الجزء الثالث حلقة القرار: الرأس إلى الأمام والقياس، فإذا كانت المسافة أكبر من الأمان تقدّم الروبوت، وإلا توقف وتراجع قليلًا، ثم نظر يسارًا بزاوية 150 درجة وقاس، ويمينًا بزاوية 30 درجة وقاس، وقارن فاختار الجهة الأوسع ودار نحوها في مكانه نحو 400 ميلي ثانية، ثم تبدأ دورة جديدة.",
        "الاختبار والتحسين: اختبر الروبوت أولًا مرفوعًا على حامل وعجلتاه في الهواء، وراقب السيناريو كاملًا: تقدم، ثم قرّب يدك فيتوقف ويتراجع وينظر يمينًا ويسارًا ويستدير. فإذا دارت عجلة إلى الخلف بدل الأمام بدّل سلكي محركها على مخرجات الدرايفر فقط. وبعد نجاح الهواء أنزله إلى الأرض واضبط العتبة وزمن الدوران على سطحك أنت، قيمة واحدة كل مرة مع تسجيل نتيجتها.",
        "أخطاء شائعة: تغذية المحركات من منفذ 5V في اللوحة فتسقط اللوحة وتعيد التشغيل عند كل إقلاع، وعلاجها بطاريات الدرايفر والأرضي المشترك. وقراءات مسافة تقفز بسبب سلك صدى مرتخٍ غالبًا لا بسبب الكود. والنزول إلى الأرض قبل اختبار الهواء فيدور الروبوت حول نفسه بسبب عجلة معكوسة. وتعديل العتبة وزمن الدوران معًا فتضيع معرفة أيّ تعديل صنع الفرق."
