        "منطق الكود: نعرّف منفذ الحساس A0 ومنفذ الريلاي 7 وثابت العتبة DRY بقيمة 700 من معايرة مثالنا. وفي setup نهيئ منفذ الريلاي مخرجًا ونكتب عليه LOW فورًا حتى نضمن أن المضخة مطفأة عند كل بداية مهما حدث. وفي loop نقرأ الرطوبة بـ analogRead ونطبعها على الشاشة التسلسلية، فإذا كانت القراءة أكبر من العتبة فالتربة عطشى: نطبع رسالة الجفاف ونشغّل الريلاي، ثم تأتي الحماية الذهبية: انتظار خمس ثوانٍ فقط ثم إطفاء المضخة حتمًا، فالري عندنا نبضة قصيرة محمية زمنيًا حتى لا تغرق النبتة ولا يفرغ الخزان. وبعدها انتظار عشر ثوانٍ للعرض والتعلم ثم قياس جديد، وفي الاستعمال الحقيقي يكون الانتظار بين الفحوص أطول بكثير.",
