        "text": "// Weather station: DHT11 + LCD I2C\n#include <DHT.h>\n#include <LiquidCrystal_I2C.h>\n\n#define DHTPIN 2\n#define DHTTYPE DHT11\n\nDHT dht(DHTPIN, DHTTYPE);\nLiquidCrystal_I2C lcd(0x27, 16, 2);\n\nvoid setup() {\n  dht.begin();\n  lcd.init();\n  lcd.backlight();\n  lcd.setCursor(0, 0);\n  lcd.print(\"Weather Station\");\n  lcd.setCursor(0, 1);\n  lcd.print(\"Reading sensor..\");\n  delay(1500);\n  lcd.clear();\n}\n\nvoid loop() {\n  float h = dht.readHumidity();\n  float t = dht.readTemperature();\n\n  if (isnan(h) || isnan(t)) {\n    lcd.setCursor(0, 0);\n    lcd.print(\"Sensor error!   \");\n    lcd.setCursor(0, 1);\n    lcd.print(\"Check DHT wiring\");\n  } else {\n    lcd.setCursor(0, 0);\n    lcd.print(\"Temp: \");\n    lcd.print(t, 1);\n    lcd.print(\" C   \");\n    lcd.setCursor(0, 1);\n    lcd.print(\"Hum : \");\n    lcd.print(h, 0);\n    lcd.print(\" %    \");\n  }\n  delay(2000);\n}"
