      "code": {
        "title": "كود قفل RFID كاملًا — تعريفات وبصمة مخوّلة، مقارنة صارمة وتهيئة، حلقة القرار",
        "text": "#include <SPI.h>\n#include <MFRC522.h>\n#include <Servo.h>\n\n#define SS_PIN 10\n#define RST_PIN 9\n\nMFRC522 rfid(SS_PIN, RST_PIN);\nServo lockServo;\n\n// Authorized card fingerprint (example — use YOUR card's UID)\nbyte allowedUID[4] = { 0xDE, 0xAD, 0xBE, 0xEF };\n\nconst int servoPin = 3;\nconst int greenLed = 5;\nconst int redLed = 6;\n\nbool isAllowed() {\n  if (rfid.uid.size != 4) return false;\n  for (byte i = 0; i < 4; i++) {\n    if (rfid.uid.uidByte[i] != allowedUID[i]) return false;\n  }\n  return true;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  SPI.begin();\n  rfid.PCD_Init();\n  lockServo.attach(servoPin);\n  lockServo.write(0);          // locked\n  pinMode(greenLed, OUTPUT);\n  pinMode(redLed, OUTPUT);\n  Serial.println(\"Lock ready\");\n}\n\nvoid loop() {\n  if (!rfid.PICC_IsNewCardPresent()) return;\n  if (!rfid.PICC_ReadCardSerial()) return;\n\n  Serial.print(\"UID: \");\n  for (byte i = 0; i < rfid.uid.size; i++) {\n    Serial.print(rfid.uid.uidByte[i], HEX);\n    Serial.print(\" \");\n  }\n  Serial.println();\n\n  if (isAllowed()) {\n    Serial.println(\"Access granted\");\n    digitalWrite(greenLed, HIGH);\n    lockServo.write(90);\n    delay(3000);\n    lockServo.write(0);\n    digitalWrite(greenLed, LOW);\n  } else {\n    Serial.println(\"Access denied\");\n    digitalWrite(redLed, HIGH);\n    delay(1000);\n    digitalWrite(redLed, LOW);\n  }\n  rfid.PICC_HaltA();\n  rfid.PCD_StopCrypto1();\n}"
      },
