        "فكرة مشروع التخرج: في كل درس سابق بنينا مشروعًا اخترناه لك وشرحناه خطوة خطوة، أما اليوم فتنقلب الأدوار: أنت تختار وأنت تخطط وأنت تبني وتختبر وتعرض. والقاعدة الأولى لا استثناء فيها: تختار مشروعًا واحدًا فقط من قائمة المشاريع المقترحة في المنصة، ولا مشروع من خارجها، فالقائمة غنية بما يكفي والإبداع يكون داخل التنفيذ والتطوير. والمشاريع المقترحة هي مشاريع هذا المستوى التي أتقنتها: روبوت يتفادى العوائق، وروبوت يتتبع الخط، ونظام ريّ ذكي للنباتات، ومحطة طقس بشاشة LCD I2C، وقفل باب ذكي بـRFID، وإنذار ضد السرقة بـPIR. وكيف تختار اختيارًا موفقًا؟ ابدأ بقلبك فاختر مشروعًا يثير فضولك فعلًا لأن الحماس وقودك عند أول عطل، ثم انظر إلى طاولتك فاختر مشروعًا تتوفر عناصره عندك كاملة أو شبه كاملة، ثم وازن التحدي: مشروع يمدّد مهارتك خطوة واحدة فوق ما تتقنه، لا سهل يملّك ولا عملاق يغرقك، وأخيرًا احسب وقتك المتاح بصدق واكتب اختيارك وشاركه مع أستاذك قبل أن تبدأ.",
        "الخطوة الأولى قبل لمس أي سلك: املأ ورقة تخطيط المشروع كاملة. في أعلاها اسمك واسم مشروعك وهدفه في جملة واحدة واضحة، ثم قائمة عناصر تضع علامة أمام كل عنصر تأكدت من وجوده بيدك فعلًا، ثم جدول منافذ: كل عنصر وأمام أي منفذ سيتصل كما تعوّدنا في كل درس، ثم مراحل بناء مرقّمة لكل مرحلة اختبارها الخاص بها، وأخيرًا خطة اختبار مكتوبة: ماذا ستجرّب بالضبط وماذا تتوقع أن يحدث إذا نجح كل شيء. ورقة مكتملة اليوم توفّر عليك ساعات حيرة غدًا، والبدء بالتوصيل قبل ملئها خطأ كلاسيكي تكتشف معه متأخرًا نقص عنصر أو منفذًا مشغولًا.",
        "مرحلة البناء تسير بقائمة تحقق وبوابات لا تتجاوزها: ابنِ الجزء الأول وحده واختبره وضع علامة ناجح في قائمتك، ولا تنتقل إلى الجزء التالي إلا بعد هذه العلامة. هكذا بنينا مشاريع المستوى كلها: الحساس وحده، ثم المشغّل وحده، ثم الجمع بينهما. وقاعدتنا الذهبية ترافقك هنا أيضًا: افصل كابل USB قبل أي توصيل أو تعديل سلك. وإذا فشل جزء في اختباره فليست هذه مصيبة بل البوابة تؤدي وظيفتها: اكتشفت العطل صغيرًا وحده بدل مطاردته لاحقًا داخل نظام كامل.",
        "مرحلة الكود تبدأ من نقطة قوية: كود درس مشروعك نفسه، فهو كود مجرّب وناجح. مهمتك ليست نسخه كما هو بل تكييفه وتطويره بفهم: شغّله أولًا كما هو وتأكد أن نظامك يطابق الدرس، ثم أدخل لمستك الصغيرة المدروسة: تغيير قيمة واحدة أو إضافة خاصية بسيطة من عندك. والمثال في كود هذا الدرس واضح: في روبوت تفادي العوائق غيّر قيمة المسافة الآمنة من 20 إلى 30 سم فيقف روبوتك أبكر ويصير أكثر حذرًا ولاحظ الفرق بنفسك في جولته. تغيير صغير مفهوم بعمق خير من كود كبير منسوخ بلا فهم، ونسخ الكود دون فهم سطر واحد منه يجعل شرحك ينهار عند أول سؤال في العرض.",
        "افتح سجل اختبار مكتوبًا فهو ذاكرة مشروعك وصديقك وقت العرض: لكل تجربة سجّل ثلاثة أمور: ما جرّبت، وماذا حدث فعلًا، وما أصلحت أو غيّرت بعدها. وعندما يظهر عطل أصلح بترتيبنا الثابت: الطاقة أولًا، ثم التوصيل سلكًا سلكًا، ثم الكود أخيرًا سطرًا سطرًا، ولا تغيّر ثلاثة أشياء دفعة واحدة بل شيئًا واحدًا ثم أعد التجربة حتى تعرف يقينًا ما الذي أصلح العطل فعلًا. وقبل يوم العرض جهّز مشروعك ليظهر كما يعمل جميلًا: رتّب الأسلاك واربط المرتخي منها برفق حتى لا يفلت سلك في منتصف عرضك الحي، وضع بطاقات صغيرة بأسماء العناصر المهمة قرب كل عنصر، وبطاقة عنوان من سطر واحد تحمل اسم مشروعك واسمك أمام مشروعك، وجهّز تغذيتك وبطارياتك ونسخة احتياطية من كودك وسجل اختبارك مرتبًا، فالتحضير الهادئ نصف العرض الناجح.",
        "العرض والتقييم: عرضك أمام الزملاء قصير ومرتب، نحو دقيقتين، وبنيته خمس خطوات: ابدأ بالمشكلة أي الحاجة التي يحلّها مشروعك في الحياة اليومية، ثم كيف بنيته باختيار مرحلتين مهمتين وشرح قرارك فيهما، ثم قدّم عرضًا حيًا عاملًا أمام الجميع فالمشروع العامل يتكلم أبلغ من أي وصف، ثم احكِ أصعب عطل واجهك وكيف أصلحته بترتيبك المنهجي، واختم بما تعلّمته وبما ستطوّره لو أُتيح لك وقت أطول، وتحدّث ببطء وثقة وانظر إلى زملائك لا إلى الأرض. وستُقيّم بأربعة معايير تعرفها من الآن: أن يعمل مشروعك بثبات أمام الجميع لا مرة واحدة بالصدفة، وتوصيل مرتب وآمن بأسلاك واضحة بلا أطراف عارية خطرة، وأن تشرح كودك بكلماتك الخاصة فهمًا لا حفظًا، وأن تجيب عن الأسئلة بهدوء وصدق. واحذر أخطاء أفسدت مشاريع تخرج كثيرة: اختيار مشروع أكبر من وقتك، وترك الاختبار الحقيقي لآخر يوم، فمشروع متوسط مكتمل ومجرّب بثبات أجمل دائمًا من مشروع عملاق لم يكتمل أبدًا."
