        "الإعداد في بيئة التطوير: كل عملنا يبقى داخل Arduino IDE التي تعرفها، لكنها لا تعرف اللوحة الجديدة إلا بعد تثبيت حزمة لوحات ESP32 الرسمية من Espressif عبر مدير اللوحات. افتح التفضيلات وأضف الرابط الإضافي الخاص بالحزمة في خانة الروابط الإضافية ثم احفظ، وبعدها افتح مدير اللوحات وابحث باسم اللوحة وثبّت الحزمة الرسمية وانتظر اكتمال التنزيل بصبر فهي أكبر من المعتاد. ثم اختر من قائمة الأدوات طراز Dev Module وهو الاختيار العام المناسب لمعظم لوحات التطوير الشائعة، وصِل الكابل واختر المنفذ الذي ظهر، وجرّب رفع سكتش بسيط للتأكد. وانتبه: في بعض نسخ اللوحة قد تحتاج إلى ضغط زر الإقلاع BOOT لحظة بدء الرفع حتى يقبل الحاسوب نقل البرنامج إليها.",
        "منطق الكود: نبدأ بالمكتبة المدمجة الخاصة بالواي فاي وهي تأتي مع حزمة اللوحة فلا تثبيت إضافيًا، ونعرّف في أعلى السكتش اسم الشبكة SSID وكلمة مرورها. اسم الشبكة في كود الدرس مثال تعليمي نائب: استبدله باسم شبكة قسمك الحقيقية التي يعطيها لك الأستاذ، أما كلمة المرور فسرّ خاص لا ننطقه أبدًا ولا نكتبه حقيقيًا في أي مثال ونضع مكانها علامات نائبة دائمًا. وتذكّر أن واي فاي هذه اللوحة يعمل بتردد 2.4GHz فقط فلا يرى الشبكات الأعلى ترددًا أبدًا. وداخل setup نفتح الشاشة التسلسلية بسرعة 115200 وهي السرعة التي سنضبط عليها الشاشة أيضًا، ثم نأمر اللوحة ببدء الاتصال. الاتصال لا يحدث في لحظة، لذلك تأتي حلقة انتظار ذكية: ما دامت حالة الاتصال ليست هي حالة النجاح تنتظر اللوحة قليلًا ثم تطبع نقطة واحدة، نقطة بعد نقطة، حتى ينجح الاتصال فتخرج من الحلقة وحدها بهدوء وتطبع عنوانها المحلي.",
        "كيف تختبر من الهاتف والحاسوب: العنوان المحلي IP هو هوية لوحتك داخل الشبكة المحلية وحدها، به يعرفها حاسوبك وهاتفك حين يكونان على الشبكة نفسها، وبه سيصلان إليها في الدروس المقبلة حيث ستصير خادمًا. افتح الشاشة التسلسلية بنفس السرعة المكتوبة في الكود لترى العنوان واضحًا بلا رموز مشوّشة، ودوّنه في دفترك. واعلم أن هذا العنوان قد يتغير عند إعادة تشغيل اللوحة، فسجّله من جديد قبل كل تجربة مقبلة، فكثير من أعطال الدروس القادمة سببها عنوان قديم تغيّر.",
        "أخطاء شائعة: إذا طالت النقاط ولم ينجح الاتصال فافحص بالترتيب ولا ترتبك: هل الشبكة تعمل بالتردد الأعلى 5GHz؟ لوحتك لا تراها فاستعمل شبكة 2.4GHz. ثم راجع اسم الشبكة وكلمة المرور حرفًا بحرف. ثم تأكد أن اللوحة المختارة في القائمة هي طراز Dev Module الصحيح وأن المنفذ المختار هو منفذ لوحتك. ثم طابِق سرعة الشاشة التسلسلية مع سرعة الكود 115200 وإلا ظهرت رموز مشوّشة. وأخطرها على الإطلاق: لا تُدخل 5V على أي منفذ في هذه اللوحة أبدًا."
