        "العناصر والتوصيل: لوحة ESP32 وكابلها، وحساس DHT11 الذي عرفته في المستوى الثالث، ولوحة تجارب وأسلاك ملونة، ومقاومة واحدة 10kΩ هي مقاومة السحب العلوي التي تسحب خط البيانات بلطف نحو التغذية فتحافظ على استقرار الإشارة، وهاتف على شبكة القسم نفسها. وقاعدة السلامة أولًا ولا تتغير أبدًا: افصل كابل USB قبل أي توصيل. ركّب الحساس ثابتًا على لوحة التجارب، وصِل سلك البيانات إلى المنفذ GPIO15 كما في الكود تمامًا، والتغذية بمنفذ 3.3V ولا توصّل إشارة الحساس أبدًا بجهد 5V، والأرضي بأرضي اللوحة، ومقاومة السحب العلوي بين خط البيانات وخط التغذية، وراجع كل سلك مرتين ثم أعد وصل الكابل.",
        "منطق الكود: نستدعي ثلاث مكتبات: الواي فاي وWebServer ومكتبة الحساس نفسها التي استعملتها في المستوى الثالث فهي تعمل هنا دون تغيير. ونكتب اسم الشبكة وكلمة مرورها وهما نوائب تعليمية تضع مكانها بيانات شبكتك الحقيقية وكلمة المرور لا تُنطق أبدًا، ونعرّف منفذ الحساس ونوعه وننشئ كائن الحساس وكائن الخادم، ومتغيران عشريان للحرارة والرطوبة يبدآن بصفر وهما ذاكرة محطتنا وسيحملان آخر قراءة صالحة. ودالة الصفحة تبني ما يراه الزائر: بنية الصفحة وترميزها وسطر ملاءمة لشاشة الهاتف وعنوان المحطة، وفي رأسها سطر اليوم الجديد: وسم تحديث تلقائي meta refresh يحمل خمس ثوانٍ وهو أمر صريح للمتصفح أن يعيد تحميل الصفحة بعدها، ثم يعرض جسم الصفحة قيمة الحرارة المخزنة بخانة عشرية واحدة وقيمة الرطوبة عددًا صحيحًا مع علامة بالمئة. وانتبه جيدًا: هذه الدالة تقرأ المتغيرات فقط ولا تلمس الحساس إطلاقًا، ولهذا تبقى سريعة وخفيفة مهما كثر الزوار.",
        "القراءة الدورية في loop: داخل loop تؤدي لوحتك واجبين متناوبين دون أن يحبس أحدهما الآخر. الواجب الأول في كل دورة خدمة الزبائن ليرد الخادم على أي طلب دون انتظار. والواجب الثاني قراءة دورية بمؤقت millis: نسأل هل مرت ثانيتان على آخر قراءة؟ فإن نعم سجّلنا لحظة القراءة وقرأنا الحرارة والرطوبة إلى متغيرين مؤقتين، ولا نخزّن بعين مغمضة: نفحص سلامة القيمتين معًا بدالة isnan، فلا نحدّث المتغيرين الدائمين إلا إذا كانت القراءتان صالحتين، وتُهمل أي قراءة فاشلة وتبقى القيمة السابقة مكانها. ولا تأخير حابس هنا: مؤقت millis يقارن الأزمنة ولا يجمّد شيئًا، فيبقى الخادم سريعًا والقراءة منتظمة، وهذا هو تطبيق القاعدة الذهبية عمليًا: لا قراءة للحساس داخل دالة الصفحة أبدًا.",
        "كيف تختبر من الهاتف: تأكد أن هاتفك متصل بشبكة القسم نفسها فمحطتنا محلية تعمل عليها فقط، واقرأ عنوان اللوحة من الشاشة التسلسلية واكتبه في متصفح هاتفك. ستظهر الصفحة بقيم قد تكون صفرين قبل أول قراءة ناجحة، ثم تستقر الأرقام وتتحدث الصفحة وحدها كل خمس ثوانٍ. قرّب راحة يدك من الحساس دون لمس خطير ولاحظ الرطوبة تصعد خلال ثوانٍ، وقارن ما تراه في الهاتف بما تطبع الشاشة التسلسلية في اللحظة نفسها.",
