        "text": "#include <WiFi.h>\n#include <HTTPClient.h>\n#include <DHT.h>\n\nconst char* ssid = \"ClassNetwork\";\nconst char* password = \"********\";\nconst char* apiKey = \"YOUR_WRITE_API_KEY\";\n\n#define DHTPIN 15\n#define DHTTYPE DHT11\nDHT dht(DHTPIN, DHTTYPE);\n\nvoid setup() {\n  Serial.begin(115200);\n  dht.begin();\n  WiFi.begin(ssid, password);\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(500);\n    Serial.print(\".\");\n  }\n  Serial.println(\"WiFi connected\");\n}\n\nvoid loop() {\n  float t = dht.readTemperature();\n  float h = dht.readHumidity();\n  if (!isnan(t) && !isnan(h) && WiFi.status() == WL_CONNECTED) {\n    HTTPClient http;\n    String url = \"https://api.thingspeak.com/update?api_key=\";\n    url += apiKey;\n    url += \"&field1=\" + String(t, 1);\n    url += \"&field2=\" + String(h, 0);\n    http.begin(url);\n    int code = http.GET();\n    Serial.print(\"ThingSpeak response: \");\n    Serial.println(code);\n    http.end();\n  }\n  delay(20000);\n}"
