window.ACADEMY_EXP_TIMERS = [];
function expTimer(fn, ms) { var t = setInterval(fn, ms); window.ACADEMY_EXP_TIMERS.push(t); return t; }
function expTimeout(fn, ms) { var t = setTimeout(fn, ms); window.ACADEMY_EXP_TIMERS.push(t); return t; }
var __expAudioCtx = null;
function expBeep(freq, durMs) {
  try {
    if (!__expAudioCtx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      __expAudioCtx = new AC();
    }
    if (__expAudioCtx.state === "suspended") __expAudioCtx.resume();
    var dur = (durMs || 200) / 1000;
    var o = __expAudioCtx.createOscillator(), g = __expAudioCtx.createGain();
    o.type = "sine";
    o.frequency.value = freq || 440;
    g.gain.value = 0.12;
    o.connect(g); g.connect(__expAudioCtx.destination);
    var t = __expAudioCtx.currentTime;
    o.start(t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.stop(t + dur + 0.05);
  } catch (e) { /* الصوت غير متاح — التجربة تعمل بصريًا */ }
}
var ACADEMY_EXPERIMENTS = window.ACADEMY_EXPERIMENTS = {};

/* ===== experiments: level 1 ===== */
"use strict";
ACADEMY_EXPERIMENTS["ohm"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box"><div class="exp-controls">' +
    '<label>جهد المصدر (Vs)<select id="ohm-vs"><option value="5" selected>5V</option><option value="3.3">3.3V</option><option value="9">9V</option></select></label>' +
    '<label>لون الـ LED (الجهد الأمامي Vf)<select id="ohm-color"><option value="2.0" selected>أحمر — 2.0V</option><option value="2.1">أصفر — 2.1V</option><option value="2.2">أخضر — 2.2V</option><option value="3.2">أزرق / أبيض — 3.2V</option></select></label>' +
    '<label>التيار المطلوب: <strong id="ohm-ival">20</strong> mA<input type="range" id="ohm-i" min="2" max="30" step="1" value="20"></label>' +
    '<p id="ohm-out" dir="rtl"></p><p id="ohm-warn" style="color:#c0392b;font-weight:700" hidden></p>' +
    '<p class="muted small">القانون: R = (Vs − Vf) ÷ I — ولا تنسَ تحويل التيار من ميلي أمبير إلى أمبير قبل القسمة. نختار عمليًا أول قيمة قياسية أكبر من المحسوبة أو مساوية لها.</p>' +
    '</div></div>';
  var selV = slot.querySelector("#ohm-vs"), selC = slot.querySelector("#ohm-color"), slider = slot.querySelector("#ohm-i");
  var ival = slot.querySelector("#ohm-ival"), out = slot.querySelector("#ohm-out"), warn = slot.querySelector("#ohm-warn");
  var standard = [100, 150, 220, 330, 470, 680, 1000];
  function render() {
    var vs = parseFloat(selV.value), vf = parseFloat(selC.value), ma = Number(slider.value);
    ival.textContent = slider.value;
    if (vs <= vf) {
      out.innerHTML = ""; warn.hidden = false;
      warn.textContent = "تنبيه: جهد المصدر (" + vs + "V) لا يكفي لتشغيل هذا الـ LED الذي يحتاج " + vf + "V أماميًا. اختر مصدرًا أعلى أو LED بجهد أمامي أقل.";
      return;
    }
    warn.hidden = true;
    var r = (vs - vf) / (ma / 1000);
    var rec = null;
    for (var i = 0; i < standard.length; i++) { if (standard[i] >= r) { rec = standard[i]; break; } }
    var html = 'المقاومة المحسوبة: <strong dir="ltr">R = (' + vs + ' − ' + vf + ') ÷ ' + (ma / 1000).toFixed(3) + ' = ' + r.toFixed(1) + ' Ω</strong><br>';
    if (rec === null) {
      html += 'المقاومة المطلوبة أكبر من 1000Ω، وهي خارج قائمة القيم القياسية هنا: اختر قيمة قياسية أعلى منها.';
    } else {
      var actual = (vs - vf) / rec * 1000;
      html += 'المقاومة القياسية الموصى بها: <strong dir="ltr">' + rec + ' Ω</strong><br>التيار الفعلي معها: <strong dir="ltr">' + actual.toFixed(1) + ' mA</strong>';
    }
    out.innerHTML = html;
  }
  selV.addEventListener("change", render); selC.addEventListener("change", render); slider.addEventListener("input", render);
  render();
};
ACADEMY_EXPERIMENTS["breadboard"] = function (slot, exp) {
  var btn = 'style="width:27px;height:27px;margin:1px;padding:0;border-radius:50%;border:1px solid #9aa3ad;background:#eef1f4;cursor:pointer;font-size:9px"';
  var html = '<div class="exp-box" style="display:block"><p class="muted small">نموذج مبسّط للوحة تجارب 400 نقطة، مرسوم بعشرة أعمدة فقط للتوضيح. انقر أي ثقب لترى الثقوب المتصلة به.</p>';
  html += '<div dir="ltr" style="overflow-x:auto"><div style="min-width:340px">';
  function rail(id, sign, color, label) {
    var s = '<div style="display:flex;align-items:center;gap:2px"><span style="width:52px;text-align:right;font-weight:700;color:' + color + '">' + label + '</span>';
    for (var c = 1; c <= 10; c++) s += '<button type="button" data-g="' + id + '" ' + btn + '></button>';
    return s + '</div>';
  }
  html += rail("rail-plus", "+", "#c0392b", "+ أحمر") + rail("rail-minus", "−", "#2471a3", "− أزرق");
  function strip(letters) {
    var s = "";
    for (var r = 0; r < letters.length; r++) {
      s += '<div style="display:flex;align-items:center;gap:2px"><span style="width:52px;text-align:right;font-weight:700">' + letters[r] + '</span>';
      for (var c = 1; c <= 10; c++) {
        var seg = c <= 5 ? 0 : 1;
        s += '<button type="button" data-g="t-' + letters[r] + '-' + seg + '" data-letter="' + letters[r] + '" data-seg="' + seg + '" ' + btn + '>' + c + '</button>';
      }
      s += '</div>';
    }
    return s;
  }
  html += '<div style="height:8px"></div>' + strip(["a", "b", "c", "d", "e"]);
  html += '<div style="text-align:center;color:#888;font-size:11px">— الفجوة الوسطى: لا اتصال عبرها —</div>' + strip(["f", "g", "h", "i", "j"]);
  html += '</div></div><p id="bb-msg" style="font-weight:700;margin-top:8px">انقر أي ثقب في اللوحة المصغرة.</p></div>';
  slot.innerHTML = html;
  var msg = slot.querySelector("#bb-msg");
  var all = slot.querySelectorAll("button[data-g]");
  all.forEach(function (b) {
    b.addEventListener("click", function () {
      var g = b.getAttribute("data-g");
      all.forEach(function (x) {
        var on = x.getAttribute("data-g") === g;
        x.style.background = on ? "#ffd23e" : "#eef1f4";
        x.style.boxShadow = on ? "0 0 6px 2px rgba(255,210,62,.8)" : "none";
      });
      if (g === "rail-plus") msg.textContent = "خط الطاقة الموجب (+): كل ثقوب هذا الخط متصلة بعضها ببعض على طول اللوحة كاملًا.";
      else if (g === "rail-minus") msg.textContent = "خط الطاقة السالب (−): كل ثقوب هذا الخط متصلة بعضها ببعض على طول اللوحة كاملًا، وهو منفصل عن خط الموجب.";
      else {
        var seg = b.getAttribute("data-seg") === "0" ? "الأعمدة 1 إلى 5" : "الأعمدة 6 إلى 10";
        msg.textContent = "الصف " + b.getAttribute("data-letter") + " ضمن " + seg + ": الثقوب الخمسة في هذه المجموعة متصلة أفقيًا، والصف المجاور والمجموعة الأخرى منفصلان عنها.";
      }
    });
  });
};
ACADEMY_EXPERIMENTS["ledwire"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box"><div class="exp-led-wrap"><div class="exp-led" id="lw-led"></div><div class="exp-led-label">LED خارجي — المنفذ 13</div></div>' +
    '<div class="exp-controls">' +
    '<label>اتجاه الـ LED<select id="lw-dir"><option value="ok" selected>الرجل الطويلة نحو المنفذ 13 — صحيحة</option><option value="rev">معكوسة: القصيرة نحو المنفذ 13</option></select></label>' +
    '<label>المقاومة<select id="lw-res"><option value="yes" selected>مقاومة 220Ω موجودة في الدائرة</option><option value="no">لا توجد مقاومة</option></select></label>' +
    '<button class="btn btn-primary" id="lw-run" type="button">شغّل الدائرة</button>' +
    '<p id="lw-verdict" style="font-weight:700;margin-top:10px">اختر الاتجاه والمقاومة ثم شغّل الدائرة.</p>' +
    '<p class="muted small">المسار الصحيح: المنفذ 13 ← المقاومة ← الرجل الطويلة ← جسم الـ LED ← الرجل القصيرة ← GND.</p>' +
    '</div></div>';
  var led = slot.querySelector("#lw-led"), dir = slot.querySelector("#lw-dir"), res = slot.querySelector("#lw-res"), verdict = slot.querySelector("#lw-verdict");
  function reset() { led.classList.remove("on"); led.style.background = ""; led.style.boxShadow = ""; verdict.style.color = ""; verdict.textContent = "اختر الاتجاه والمقاومة ثم شغّل الدائرة."; }
  dir.addEventListener("change", reset); res.addEventListener("change", reset);
  slot.querySelector("#lw-run").addEventListener("click", function () {
    led.classList.remove("on"); verdict.style.color = "";
    if (dir.value === "rev") {
      verdict.textContent = "لا يضيء: الـ LED معكوس القطبية. الصمام يمرّر التيار في اتجاه واحد فقط؛ أخرجه واقلبه بحيث تتجه الرجل الطويلة نحو المنفذ والمقاومة.";
      return;
    }
    if (res.value === "no") {
      verdict.style.color = "#c0392b";
      verdict.textContent = "خطر: تيار كبير قد يحرق الـ LED — لا توجد مقاومة تحدّ التيار. أطفئ فورًا وركّب مقاومة 220Ω.";
      led.classList.add("on");
      expTimeout(function () { led.classList.remove("on"); }, 400);
      return;
    }
    verdict.style.color = "#1e8449";
    verdict.textContent = "يضيء بأمان: الاتجاه صحيح ومقاومة 220Ω تحدّ التيار وتحمي الصمام.";
    led.classList.add("on");
  });
};
ACADEMY_EXPERIMENTS["vars"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box"><div class="exp-led-wrap"><div class="exp-led" id="vr-led"></div><div class="exp-led-label" id="vr-label">LED — المنفذ 13</div></div>' +
    '<div class="exp-controls">' +
    '<label>قيمة waitTime: <strong id="vr-wval">250</strong> ms<input type="range" id="vr-wait" min="100" max="2000" step="50" value="250"></label>' +
    '<label>قيمة ledPin<select id="vr-pin"><option value="9">9</option><option value="10">10</option><option value="13" selected>13</option></select></label>' +
    '<pre id="vr-code" dir="ltr" style="text-align:left;background:#141a22;color:#e6edf3;padding:10px;border-radius:8px;font-size:12px;overflow-x:auto"></pre>' +
    '<p class="muted small">غيّر القيمة في سطر الإعلان الواحد في الأعلى (المظلّل)، فتتغير في كل أسطر البرنامج معًا: هذا هو درس المتغيرات.</p>' +
    '</div></div>';
  var led = slot.querySelector("#vr-led"), wait = slot.querySelector("#vr-wait"), pin = slot.querySelector("#vr-pin");
  var wval = slot.querySelector("#vr-wval"), label = slot.querySelector("#vr-label"), code = slot.querySelector("#vr-code");
  var token = 0, on = false;
  function renderCode() {
    var p = pin.value, w = wait.value;
    wval.textContent = w; label.textContent = "LED — المنفذ " + p;
    var hl = 'style="background:#5a4a12;display:block"';
    code.innerHTML =
      '<span ' + hl + '>int ledPin = ' + p + ';</span>' +
      '<span ' + hl + '>int waitTime = ' + w + ';</span>' + "\n" +
      'void setup() {\n  pinMode(' + p + ', OUTPUT);\n}\n\n' +
      'void loop() {\n  digitalWrite(' + p + ', HIGH);\n  delay(' + w + ');\n  digitalWrite(' + p + ', LOW);\n  delay(' + w + ');\n}';
  }
  function start() {
    var my = ++token; on = false; led.classList.remove("on");
    function step() {
      if (my !== token) return;
      on = !on; led.classList.toggle("on", on);
      expTimeout(step, Number(wait.value));
    }
    step();
  }
  wait.addEventListener("input", function () { renderCode(); start(); });
  pin.addEventListener("change", function () { renderCode(); start(); });
  renderCode(); start();
};
ACADEMY_EXPERIMENTS["pwm"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box"><div class="exp-led-wrap"><div id="pw-led" style="width:64px;height:64px;border-radius:50%;border:2px solid #9aa3ad;margin:0 auto"></div><div class="exp-led-label">LED — المنفذ 9</div></div>' +
    '<div class="exp-controls">' +
    '<label>قيمة السطوع: <strong id="pw-val">0</strong> من 255<input type="range" id="pw-slider" min="0" max="255" step="1" value="0"></label>' +
    '<p>الأمر: <strong dir="ltr" id="pw-cmd">analogWrite(9, 0)</strong></p>' +
    '<p>دورة العمل (Duty): <strong dir="ltr" id="pw-duty">0%</strong> — الجهد التقريبي: <strong dir="ltr" id="pw-volt">0.00V</strong></p>' +
    '<button class="btn btn-primary" id="pw-fade" type="button">تدرّج تلقائي (fade)</button>' +
    '<p class="muted small">القيمة 0 انطفاء تام، و 255 أقصى سطوع، وبينهما ترى العين متوسط نبضات PWM سطوعًا متدرجًا.</p>' +
    '</div></div>';
  var led = slot.querySelector("#pw-led"), slider = slot.querySelector("#pw-slider"), fading = false, token = 0, stepv = 5;
  function render() {
    var v = Number(slider.value), t = v / 255;
    slot.querySelector("#pw-val").textContent = slider.value;
    slot.querySelector("#pw-cmd").textContent = "analogWrite(9, " + v + ")";
    slot.querySelector("#pw-duty").textContent = (t * 100).toFixed(0) + "%";
    slot.querySelector("#pw-volt").textContent = (t * 5).toFixed(2) + "V";
    led.style.background = "rgba(255,209,62," + (0.06 + 0.94 * t).toFixed(3) + ")";
    led.style.boxShadow = v === 0 ? "none" : "0 0 " + (10 + 45 * t).toFixed(0) + "px " + (4 + 12 * t).toFixed(0) + "px rgba(255,210,62,.65)";
  }
  function fadeStep(my) {
    if (!fading || my !== token) return;
    var v = Number(slider.value) + stepv;
    if (v >= 255) { v = 255; stepv = -5; }
    if (v <= 0) { v = 0; stepv = 5; }
    slider.value = String(v); render();
    expTimeout(function () { fadeStep(my); }, 30);
  }
  slider.addEventListener("input", render);
  slot.querySelector("#pw-fade").addEventListener("click", function () {
    fading = !fading;
    this.textContent = fading ? "إيقاف التدرّج" : "تدرّج تلقائي (fade)";
    if (fading) { var my = ++token; fadeStep(my); } else { token++; }
  });
  render();
};
ACADEMY_EXPERIMENTS["loops"] = function (slot, exp) {
  var dots = "";
  for (var i = 0; i < 3; i++) dots += '<div style="text-align:center"><div id="lp-' + i + '" style="width:52px;height:52px;border-radius:50%;border:2px solid #9aa3ad;background:#eef1f4;margin:0 auto"></div><div class="exp-led-label">المنفذ ' + (8 + i) + '</div></div>';
  slot.innerHTML =
    '<div class="exp-box" style="display:block"><div style="display:flex;gap:22px;justify-content:center;flex-wrap:wrap">' + dots + '</div>' +
    '<div class="exp-controls" style="margin-top:12px">' +
    '<label>زمن delay: <strong id="lp-dval">300</strong> ms<input type="range" id="lp-delay" min="100" max="800" step="50" value="300"></label>' +
    '<label>نوع الحلقة<select id="lp-mode"><option value="for" selected>for — عدد مرات معروف</option><option value="while">while — تكرار بشرط</option></select></label>' +
    '<button class="btn btn-primary" id="lp-toggle" type="button">تشغيل التتابع</button>' +
    '<p id="lp-status" style="font-weight:700;margin-top:10px">متوقف. اختر نوع الحلقة ثم اضغط تشغيل.</p>' +
    '</div></div>';
  var delayEl = slot.querySelector("#lp-delay"), mode = slot.querySelector("#lp-mode"), status = slot.querySelector("#lp-status"), btn = slot.querySelector("#lp-toggle");
  var running = false, token = 0, idx = 0;
  function paint() {
    for (var j = 0; j < 3; j++) {
      var d = slot.querySelector("#lp-" + j), on = running && j === idx;
      d.style.background = on ? "#ffd23e" : "#eef1f4";
      d.style.boxShadow = on ? "0 0 26px 8px rgba(255,210,62,.65)" : "none";
    }
  }
  function statusNow() {
    if (!running) { status.textContent = "متوقف."; return; }
    var pin = 8 + idx;
    if (mode.value === "for") status.innerHTML = 'الصمام المضيء: المنفذ ' + pin + ' — <span dir="ltr">for (int i = 0; i &lt; 3; i++) — i = ' + idx + '</span>';
    else status.innerHTML = 'الصمام المضيء: المنفذ ' + pin + ' — <span dir="ltr">counter = ' + idx + ' ; counter++</span> (يستمر ما دام العداد أصغر من 3)';
  }
  function step(my) {
    if (!running || my !== token) return;
    paint(); statusNow();
    expTimeout(function () {
      if (!running || my !== token) return;
      idx = (idx + 1) % 3; step(my);
    }, Number(delayEl.value));
  }
  delayEl.addEventListener("input", function () { slot.querySelector("#lp-dval").textContent = delayEl.value; });
  mode.addEventListener("change", statusNow);
  btn.addEventListener("click", function () {
    running = !running;
    btn.textContent = running ? "إيقاف التتابع" : "تشغيل التتابع";
    if (running) { idx = 0; var my = ++token; step(my); } else { token++; paint(); statusNow(); }
  });
  paint();
};
ACADEMY_EXPERIMENTS["debugfix"] = function (slot, exp) {
  var rounds = [
    { code: "void loop() {\n  digitalWrite(13, HIGH)\n  delay(1000);\n}", opts: ["أضف ; في نهاية سطر digitalWrite", "احذف سطر delay نهائيًا", "غيّر HIGH إلى LOW"], correct: 0 },
    { code: "void loop() {\n  digitalWrite(13, HIGH);\n  delay(1000);", opts: ["أضف ; ثانية بعد سطر delay", "أضف } في نهاية الدالة لإغلاقها", "أضف قوس فتح آخر في البداية"], correct: 1 },
    { code: "void setup {\n  pinMode(13, OUTPUT);\n}", opts: ["احذف كلمة void", "غيّر pinMode إلى pinmode", "اكتبها بأقواس بعد اسم الدالة: void setup()"], correct: 2 }
  ];
  slot.innerHTML =
    '<div class="exp-box" style="display:block"><p style="font-weight:700">أين الخطأ؟ — الجولة <span id="dbg-round">1</span> من 3</p>' +
    '<pre id="dbg-code" dir="ltr" style="text-align:left;background:#141a22;color:#e6edf3;padding:10px;border-radius:8px;font-size:13px;overflow-x:auto"></pre>' +
    '<div id="dbg-opts" style="display:flex;flex-direction:column;gap:8px"></div>' +
    '<p id="dbg-fb" style="font-weight:700;margin-top:10px"></p>' +
    '<p>نتيجتك: <strong id="dbg-score">0/3</strong></p>' +
    '<button class="btn btn-ghost" id="dbg-restart" type="button">إعادة اللعبة</button></div>';
  var ri = 0, score = 0, tried = false, done = false;
  var codeEl = slot.querySelector("#dbg-code"), optsEl = slot.querySelector("#dbg-opts"), fb = slot.querySelector("#dbg-fb");
  function renderRound() {
    tried = false; done = false;
    slot.querySelector("#dbg-round").textContent = String(Math.min(ri + 1, 3));
    slot.querySelector("#dbg-score").textContent = score + "/3";
    codeEl.textContent = rounds[ri].code; fb.textContent = ""; fb.style.color = "";
    optsEl.innerHTML = "";
    rounds[ri].opts.forEach(function (op, oi) {
      var b = document.createElement("button");
      b.type = "button"; b.className = "btn btn-ghost"; b.textContent = op; b.style.textAlign = "right";
      b.addEventListener("click", function () { choose(oi, b); });
      optsEl.appendChild(b);
    });
  }
  function choose(oi, b) {
    if (done) return;
    if (oi === rounds[ri].correct) {
      if (!tried) score++;
      done = true; expBeep(880, 120);
      fb.style.color = "#1e8449"; fb.textContent = "✓ صحيح! هذا هو الإصلاح.";
      slot.querySelector("#dbg-score").textContent = score + "/3";
      expTimeout(function () {
        ri++;
        if (ri < rounds.length) renderRound();
        else { codeEl.textContent = ""; optsEl.innerHTML = ""; fb.style.color = ""; fb.textContent = "انتهت الجولات الثلاث. نتيجتك النهائية: " + score + "/3 — أعد اللعبة لتحسينها."; slot.querySelector("#dbg-round").textContent = "3"; }
      }, 1000);
    } else {
      tried = true; expBeep(220, 120);
      fb.style.color = "#c0392b"; fb.textContent = "✗ ليس هذا هو الخطأ. فكّر: اقرأ السطر سطرًا وقارنه بما تعلمته، ثم جرّب خيارًا آخر.";
    }
  }
  slot.querySelector("#dbg-restart").addEventListener("click", function () { ri = 0; score = 0; renderRound(); });
  renderRound();
};
ACADEMY_EXPERIMENTS["traffic"] = function (slot, exp) {
  var phases = [
    { name: "الأخضر", dur: 5000, on: ["green"] },
    { name: "الأصفر", dur: 1000, on: ["yellow"] },
    { name: "الأحمر", dur: 5000, on: ["red"] }
  ];
  var meta = { red: { pin: 8, label: "الأحمر", color: "#e74c3c" }, yellow: { pin: 9, label: "الأصفر", color: "#f5c518" }, green: { pin: 10, label: "الأخضر", color: "#2ecc71" } };
  function circle(id, label) {
    return '<div style="text-align:center"><div id="tf-' + id + '" style="width:58px;height:58px;border-radius:50%;border:2px solid #555;background:#3a3f4a;margin:0 auto"></div><div class="exp-led-label">' + label + '</div></div>';
  }
  slot.innerHTML =
    '<div class="exp-box" style="display:block"><div style="display:flex;gap:20px;justify-content:center;flex-wrap:wrap">' +
    circle("red", "أحمر — المنفذ 8") + circle("yellow", "أصفر — المنفذ 9") + circle("green", "أخضر — المنفذ 10") + '</div>' +
    '<div style="text-align:center;margin-top:12px"><button class="btn btn-primary" id="tf-toggle" type="button">تشغيل الإشارة</button>' +
    '<p id="tf-phase" style="font-weight:700;margin-top:10px">متوقفة. اضغط تشغيل لبدء التسلسل.</p>' +
    '<p id="tf-pins" dir="rtl" class="muted"></p>' +
    '<p class="muted small">التسلسل في هذه المحاكاة هو تسلسل كود الدرس نفسه: أخضر 5 ثوانٍ ← أصفر ثانية واحدة ← أحمر 5 ثوانٍ، ثم تتكرر الدورة.</p></div></div>';
  var running = false, token = 0, phaseIdx = 0;
  var phaseEl = slot.querySelector("#tf-phase"), pinsEl = slot.querySelector("#tf-pins"), btn = slot.querySelector("#tf-toggle");
  function paint() {
    var ph = running ? phases[phaseIdx] : null;
    ["red", "yellow", "green"].forEach(function (k) {
      var d = slot.querySelector("#tf-" + k), on = ph && ph.on.indexOf(k) >= 0;
      d.style.background = on ? meta[k].color : "#3a3f4a";
      d.style.boxShadow = on ? "0 0 26px 8px " + meta[k].color + "66" : "none";
    });
    if (!ph) { phaseEl.textContent = "متوقفة. اضغط تشغيل لبدء التسلسل."; pinsEl.textContent = ""; return; }
    phaseEl.textContent = "المرحلة الحالية: " + ph.name + " (" + (ph.dur / 1000) + " ثوانٍ)";
    pinsEl.innerHTML = ph.on.map(function (k) { return "المنفذ " + meta[k].pin + " = HIGH (" + meta[k].label + ")"; }).join(" — ");
  }
  function step(my) {
    if (!running || my !== token) return;
    paint();
    expTimeout(function () {
      if (!running || my !== token) return;
      phaseIdx = (phaseIdx + 1) % phases.length; step(my);
    }, phases[phaseIdx].dur);
  }
  btn.addEventListener("click", function () {
    running = !running;
    btn.textContent = running ? "إيقاف الإشارة" : "تشغيل الإشارة";
    if (running) { phaseIdx = 0; var my = ++token; step(my); } else { token++; paint(); }
  });
  paint();
};

/* ===== experiments: level 2 ===== */
"use strict";
ACADEMY_EXPERIMENTS["serial"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box"><div class="exp-controls">' +
    '<p class="muted">هذه محاكاة للشاشة التسلسلية: عند بدء الطباعة يصل سطر جديد كل 600 ميلي ثانية، تمامًا كما يطبع برنامج العداد في الدرس. جرّب الإيقاف والمسح، ولاحظ أن العداد لا يعود إلى الصفر إلا بمسح الشاشة.</p>' +
    '<label>سرعة الاتصال Baud: <select id="sm-baud" dir="ltr"><option>9600</option><option>115200</option></select></label> ' +
    '<button class="btn btn-primary btn-small" id="sm-start" type="button">بدء الطباعة</button> ' +
    '<button class="btn btn-ghost btn-small" id="sm-stop" type="button">إيقاف</button> ' +
    '<button class="btn btn-ghost btn-small" id="sm-clear" type="button">مسح الشاشة</button>' +
    '<div id="sm-console" dir="ltr" style="background:#0d1117;color:#7ee787;font-family:monospace;font-size:13px;height:160px;overflow:auto;padding:8px;border-radius:8px;margin-top:10px;text-align:left;white-space:pre-line"></div>' +
    '</div></div>';
  const box = slot.querySelector("#sm-console");
  const startBtn = slot.querySelector("#sm-start"), stopBtn = slot.querySelector("#sm-stop");
  let counter = 0, running = false, timer = null;
  function line(txt) { box.textContent += txt + "\n"; box.scrollTop = box.scrollHeight; }
  line("Program started");
  function tick() {
    line("Counter: " + counter + "   |   millis: " + (counter * 600));
    counter++;
  }
  startBtn.addEventListener("click", () => {
    if (running) return;
    running = true; startBtn.disabled = true;
    tick();
    timer = expTimer(tick, 600);
  });
  stopBtn.addEventListener("click", () => {
    if (!running) return;
    running = false; startBtn.disabled = false;
    if (timer) { clearInterval(timer); timer = null; }
    line("-- paused --");
  });
  slot.querySelector("#sm-clear").addEventListener("click", () => {
    box.textContent = ""; counter = 0;
    line("Program started");
  });
  slot.querySelector("#sm-baud").addEventListener("change", (e) => {
    line("-- baud = " + e.target.value + " (يجب أن يطابق Serial.begin) --");
  });
};
