ACADEMY_EXPERIMENTS["funcstep"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box">' +
    '<div class="exp-led-wrap"><div class="exp-led" id="fs-led"></div><div class="exp-led-label">LED — المنفذ 9</div></div>' +
    '<div class="exp-controls">' +
    '<p class="muted">استدعِ كل دالة بنفسك ولاحظ سجلّ الاستدعاءات: التعريف وحده لا ينفّذ شيئًا، والتنفيذ يبدأ عند الاستدعاء فقط.</p>' +
    '<button class="btn btn-primary btn-small" id="fs-blink" type="button">استدعِ <span dir="ltr">blinkOnce()</span></button> ' +
    '<button class="btn btn-primary btn-small" id="fs-chase" type="button">استدعِ <span dir="ltr">chase()</span></button> ' +
    '<button class="btn btn-ghost btn-small" id="fs-off" type="button">استدعِ <span dir="ltr">allOff()</span></button> ' +
    '<button class="btn btn-ghost btn-small" id="fs-loop" type="button">تشغيل <span dir="ltr">loop()</span></button>' +
    '<div id="fs-log" dir="ltr" style="background:#0d1117;color:#7ee787;font-family:monospace;font-size:13px;height:120px;overflow:auto;padding:8px;border-radius:8px;margin-top:10px;text-align:left;white-space:pre-line"></div>' +
    '</div></div>';
  const led = slot.querySelector("#fs-led"), log = slot.querySelector("#fs-log");
  let pending = [], busy = false;
  function say(t) { log.textContent += t + "\n"; log.scrollTop = log.scrollHeight; }
  function later(fn, ms) { pending.push(expTimeout(fn, ms)); }
  function setLed(on) { led.classList.toggle("on", on); }
  function blinkOnce(done) {
    say("→ blinkOnce()");
    setLed(true);
    later(() => { setLed(false); say("← blinkOnce() done"); if (done) done(); }, 400);
  }
  function chase(done) {
    say("→ chase()");
    let step = 0;
    function next() {
      if (step >= 6) { setLed(false); say("← chase() done"); if (done) done(); return; }
      setLed(step % 2 === 0); step++;
      later(next, 180);
    }
    next();
  }
  function allOff() {
    pending.forEach(t => clearTimeout(t)); pending = [];
    busy = false; setLed(false);
    say("→ allOff()"); say("← allOff() done");
  }
  slot.querySelector("#fs-blink").addEventListener("click", () => { if (!busy) { busy = true; blinkOnce(() => { busy = false; }); } });
  slot.querySelector("#fs-chase").addEventListener("click", () => { if (!busy) { busy = true; chase(() => { busy = false; }); } });
  slot.querySelector("#fs-off").addEventListener("click", allOff);
  slot.querySelector("#fs-loop").addEventListener("click", () => {
    if (busy) return;
    busy = true; say("== loop() starts ==");
    blinkOnce(() => chase(() => { allOff(); say("== loop() ends =="); }));
  });
  say("// call log — جرّب الأزرار");
};
