"use strict";
ACADEMY_EXPERIMENTS["libsteps"] = function (slot, exp) {
  var steps = [
    "افتح مدير المكتبات من قائمة Sketch",
    "ابحث عن المكتبة وثبّتها Install",
    "اكتب #include <Library.h> في أعلى السكتش",
    "استعمل دوال المكتبة داخل الكود"
  ];
  slot.innerHTML =
    '<div class="exp-box" style="display:block">' +
    '<p class="muted">رتّب خطوات استعمال مكتبة جديدة: اضغط البطاقات بالترتيب الصحيح من الأولى إلى الرابعة.</p>' +
    '<div id="ls-cards" style="display:grid;gap:.5rem;margin:.6rem 0"></div>' +
    '<p id="ls-hint" class="small" style="min-height:1.2em;font-weight:700"></p>' +
    '<button class="btn btn-ghost btn-small" id="ls-shuffle" type="button">إعادة الخلط</button>' +
    '</div>';
  var cardsEl = slot.querySelector("#ls-cards"), hint = slot.querySelector("#ls-hint");
  var next = 0;
  function render() {
    next = 0; hint.textContent = "";
    var order = [0, 1, 2, 3];
    for (var i = order.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = order[i]; order[i] = order[j]; order[j] = t; }
    if (order.join() === "0,1,2,3") order.reverse();
    cardsEl.innerHTML = "";
    order.forEach(function (pos) {
      var b = document.createElement("button");
      b.type = "button"; b.className = "btn btn-ghost"; b.style.textAlign = "right";
      b.textContent = steps[pos]; b.setAttribute("data-pos", pos);
      b.addEventListener("click", function () {
        if (b.disabled) return;
        if (Number(b.getAttribute("data-pos")) === next) {
          next++;
          b.disabled = true;
          b.style.background = "#d9f7d2"; b.style.borderColor = "#2e9e4f";
          b.textContent = "✓ " + next + " — " + steps[pos];
          hint.textContent = next === 4 ? "🎉 أحسنت! هذا هو الترتيب الصحيح كاملًا: تثبيت، ثم استدعاء، ثم استعمال." : "صحيح! أكمل بالخطوة الموالية.";
          hint.style.color = "#2e9e4f";
        } else {
          b.style.background = "#fbdcdc"; b.style.borderColor = "#d33";
          hint.textContent = "ليست هذه الخطوة الآن. فكّر: أين نحن من رحلة المكتبة؟ المطلوب الآن هو الخطوة رقم " + (next + 1) + ".";
          hint.style.color = "#c22";
          expTimeout(function () { b.style.background = ""; b.style.borderColor = ""; }, 450);
        }
      });
      cardsEl.appendChild(b);
    });
  }
  slot.querySelector("#ls-shuffle").addEventListener("click", render);
  render();
};
ACADEMY_EXPERIMENTS["dht"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box" style="display:block">' +
    '<div class="exp-controls">' +
    '<label>الحرارة: <strong id="dht-tv">24</strong> °C<input type="range" id="dht-t" min="-5" max="50" step="0.5" value="24"></label>' +
    '<label>الرطوبة: <strong id="dht-hv">55</strong> %<input type="range" id="dht-h" min="10" max="95" step="1" value="55"></label>' +
    '</div>' +
    '<p id="dht-note" class="small" style="color:#c22;font-weight:700" hidden>خارج مجال قياس DHT11 الحقيقي — الحساس الحقيقي لن يعطي قراءة موثوقة</p>' +
    '<div style="display:flex;gap:1.5rem;flex-wrap:wrap;align-items:center;margin:.5rem 0"><div style="font-size:1.6rem;font-weight:800">🌡 <span id="dht-rt">--</span> °C</div><div style="font-size:1.6rem;font-weight:800">💧 <span id="dht-rh">--</span> %</div></div>' +
    '<button class="btn btn-primary btn-small" id="dht-read" type="button">اقرأ الحساس الآن</button> ' +
    '<label class="small"><input type="checkbox" id="dht-auto"> قراءة تلقائية كل ثانيتين</label>' +
    '<div id="dht-log" dir="ltr" style="font-family:monospace;font-size:.82rem;background:#0d1526;color:#9fe8a9;padding:.5rem;border-radius:8px;margin-top:.6rem;min-height:2.2em;text-align:left"></div>' +
    '<p class="muted small">مجال DHT11 الحقيقي: حرارة 0–50 °C ورطوبة 20–90 %. القراءة هنا فيها ضجيج قياس بسيط كما في الحساس الحقيقي.</p>' +
    '</div>';
  var tS = slot.querySelector("#dht-t"), hS = slot.querySelector("#dht-h"),
      tV = slot.querySelector("#dht-tv"), hV = slot.querySelector("#dht-hv"),
      note = slot.querySelector("#dht-note"), log = slot.querySelector("#dht-log"), autoId = null;
  function checkRange() {
    var t = Number(tS.value), h = Number(hS.value);
    tV.textContent = t; hV.textContent = h;
    note.hidden = !(t < 0 || t > 50 || h < 20 || h > 90);
  }
  function read() {
    var t = Number(tS.value) + (Math.random() * 0.8 - 0.4);
    var h = Number(hS.value) + (Math.random() * 0.8 - 0.4);
    slot.querySelector("#dht-rt").textContent = t.toFixed(1);
    slot.querySelector("#dht-rh").textContent = h.toFixed(0);
    var line = document.createElement("div");
    line.textContent = "Temperature: " + t.toFixed(1) + " C | Humidity: " + h.toFixed(0) + " %";
    log.appendChild(line);
    while (log.children.length > 5) log.removeChild(log.firstChild);
  }
  tS.addEventListener("input", checkRange); hS.addEventListener("input", checkRange);
  slot.querySelector("#dht-read").addEventListener("click", read);
  slot.querySelector("#dht-auto").addEventListener("change", function (e) {
    if (e.target.checked) { read(); autoId = expTimer(read, 2000); }
    else if (autoId) { clearInterval(autoId); autoId = null; }
  });
  checkRange();
};
