ACADEMY_EXPERIMENTS["pir"] = function (slot, exp) {
  slot.innerHTML =
    '<div class="exp-box">' +
    '<div class="exp-led-wrap"><div class="exp-led" id="pir-led"></div><div class="exp-led-label">تنبيه الحركة</div></div>' +
    '<div class="exp-controls">' +
    '<p id="pir-state" style="font-weight:800;font-size:1.1rem">لا حركة — المكان هادئ</p>' +
    '<label>زمن البقاء بعد آخر حركة: <strong id="pir-hv">4</strong> ثوانٍ<input type="range" id="pir-h" min="2" max="8" step="1" value="4"></label>' +
    '<button class="btn btn-primary" id="pir-go" type="button">🚶 مرّ شخص أمام الحساس</button>' +
    '<p class="muted small">في الواقع يحتاج حساس PIR وقت إحماء قصيرًا بعد التشغيل (نحو 30 ثانية) حتى يستقر، ومرور جديد أثناء العدّ يعيد ضبط زمن البقاء من جديد.</p>' +
    '</div></div>';
  var led = slot.querySelector("#pir-led"), st = slot.querySelector("#pir-state"),
      hs = slot.querySelector("#pir-h"), remain = 0, timer = null;
  hs.addEventListener("input", function () { slot.querySelector("#pir-hv").textContent = hs.value; });
  slot.querySelector("#pir-go").addEventListener("click", function () {
    remain = Number(hs.value);
    led.classList.add("on");
    st.textContent = "🔴 تم كشف حركة! — يبقى التنبيه " + remain + " ثوانٍ";
    st.style.color = "#c22";
    if (timer) return;
    timer = expTimer(function () {
      remain--;
      if (remain <= 0) {
        clearInterval(timer); timer = null;
        led.classList.remove("on");
        st.textContent = "لا حركة — المكان هادئ"; st.style.color = "";
      } else {
        st.textContent = "🔴 تم كشف حركة! — يبقى التنبيه " + remain + " ثوانٍ";
      }
    }, 1000);
  });
};
