ACADEMY_EXPERIMENTS["gradplan"] = function (slot, exp) {
  const projects = {
    "روبوت يتفادى العوائق": ["هيكل بعجلتين وكرة دوّارة", "محركا DC", "درايفر L298N", "حساس HC-SR04", "محرك سيرفو", "علبة بطاريات 4×AA", "لوحة Uno"],
    "روبوت يتتبع الخط": ["هيكل بعجلتين وكرة دوّارة", "حساسا خط IR", "محركا DC", "درايفر L298N", "علبة بطاريات 4×AA", "شريط أسود على أرضية بيضاء"],
    "نظام ريّ ذكي": ["حساس رطوبة التربة", "وحدة ريلاي", "مضخة صغيرة", "مصدر طاقة مستقل للمضخة", "خزان ماء وأنبوب", "أصيص ونبتة"],
    "محطة طقس LCD": ["حساس DHT11", "مقاومة سحب علوي 10kΩ", "شاشة LCD I2C 16×2", "لوحة Uno وأسلاك"],
    "قفل باب RFID": ["قارئ RC522 وبطاقات", "محرك سيرفو SG90", "صمامان LED مع مقاومتي 220Ω", "نموذج باب صغير"],
    "إنذار ضد السرقة PIR": ["حساس PIR", "جرس سلبي", "LED أحمر مع مقاومة 220Ω", "زر إيقاف مع مقاومة سحب سفلي 10kΩ"]
  };
  const steps = ["خطّطت ورسمت المخطط", "جرّبت كل جزء وحده", "وصّلت خطوة بخطوة", "كتبت الكود واختبرته", "جهّزت عرضي أمام الزملاء"];
  slot.innerHTML = `<div class="exp-box">
    <label>اختر مشروع تخرّجك — من المشاريع المقترحة في المنصة فقط:
      <select id="gp-sel" style="display:block;width:100%;margin:8px 0;padding:8px">
        <option value="">— اختر مشروعك —</option>
        ${Object.keys(projects).map(p => `<option>${p}</option>`).join("")}
      </select></label>
    <div id="gp-body"></div>
    <p id="gp-summary" style="font-weight:bold">مشروعي: … — أكملت 0 من 5 خطوات</p></div>`;
  const sel = slot.querySelector("#gp-sel"), body = slot.querySelector("#gp-body"), sum = slot.querySelector("#gp-summary");
  function update() {
    const boxes = body.querySelectorAll("input[type=checkbox]");
    let n = 0; boxes.forEach(b => { if (b.checked) n++; });
    const name = sel.value || "…";
    sum.textContent = "مشروعي: " + name + " — أكملت " + n + " من 5 خطوات" + (sel.value && n === 5 ? " — 🎉 خطتك كاملة — جاهز للتنفيذ والعرض!" : "");
  }
  sel.addEventListener("change", () => {
    if (!sel.value) { body.innerHTML = ""; update(); return; }
    body.innerHTML = "<p><strong>عناصر مشروعك:</strong></p><ul class='nice-list'>" +
      projects[sel.value].map(c => "<li>" + c + "</li>").join("") + "</ul>" +
      "<p><strong>قائمة تحقق المنهجية:</strong></p>" +
      steps.map(s => `<label style="display:block;margin:5px 0"><input type="checkbox"> ${s}</label>`).join("");
    body.querySelectorAll("input[type=checkbox]").forEach(b => b.addEventListener("change", update));
    update();
  });
};

