"use strict";

/* ===== 5-01: محاكاة الاتصال بالواي فاي ===== */
ACADEMY_EXPERIMENTS["wificonnect"] = function (slot, exp) {
  slot.innerHTML = `<div class="exp-box">
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end">
      <label>اسم الشبكة <span dir="ltr">SSID</span><input id="wf-ssid" type="text" dir="ltr" value="ClassroomWiFi" style="display:block"></label>
      <label>كلمة المرور<input id="wf-pass" type="password" dir="ltr" value="class1234" style="display:block"></label>
      <span id="wf-chip" style="padding:5px 12px;border-radius:20px;background:#e5e7eb;font-weight:bold">غير متصل</span>
    </div>
    <div id="wf-log" dir="ltr" style="background:#111827;color:#a7f3d0;font-family:monospace;font-size:13px;border-radius:8px;padding:10px 12px;margin:10px 0;min-height:86px;white-space:pre-line;text-align:left">Serial Monitor — 115200</div>
    <button class="btn btn-primary btn-small" id="wf-connect" type="button">اتصل بالشبكة</button>
    <button class="btn btn-ghost btn-small" id="wf-disconnect" type="button">قطع الاتصال</button></div>`;
  const ssid = slot.querySelector("#wf-ssid"), log = slot.querySelector("#wf-log"), chip = slot.querySelector("#wf-chip");
  let base = "Serial Monitor — 115200";
  function line(s) { log.textContent += "\n" + s; }
  slot.querySelector("#wf-connect").addEventListener("click", () => {
    const name = ssid.value.trim();
    log.textContent = base;
    if (!name) {
      chip.textContent = "غير متصل"; chip.style.background = "#e5e7eb";
      line("Error: SSID is empty");
      return;
    }
    chip.textContent = "جارٍ الاتصال…"; chip.style.background = "#fde68a";
    line("Connecting to " + name);
    expTimeout(() => line(". . ."), 700);
    expTimeout(() => {
      line("Connected!");
      line("IP address: 192.168.1.50");
      chip.textContent = "متصل ✓"; chip.style.background = "#bbf7d0";
    }, 1600);
  });
  slot.querySelector("#wf-disconnect").addEventListener("click", () => {
    log.textContent = base + "\nDisconnected";
    chip.textContent = "غير متصل"; chip.style.background = "#e5e7eb";
  });
};

