ACADEMY_EXPERIMENTS["webdht"] = function (slot, exp) {
  slot.innerHTML = `<div class="exp-box">
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      <div style="flex:1;min-width:130px;background:#fef3c7;border-radius:12px;padding:12px;text-align:center">🌡️ الحرارة<br><strong id="wd-t" style="font-size:26px">26.0</strong> °C</div>
      <div style="flex:1;min-width:130px;background:#dbeafe;border-radius:12px;padding:12px;text-align:center">💧 الرطوبة<br><strong id="wd-h" style="font-size:26px">55</strong> %</div>
    </div>
    <div class="exp-controls">
      <label>الحرارة الأساسية: <strong id="wd-tv">26</strong><input type="range" id="wd-ts" min="20" max="35" step="0.5" value="26"></label>
      <label>الرطوبة الأساسية: <strong id="wd-hv">55</strong><input type="range" id="wd-hs" min="30" max="80" step="1" value="55"></label>
    </div>
    <label style="display:block;margin:6px 0"><input type="checkbox" id="wd-auto" checked> تحديث تلقائي</label>
    <p>آخر تحديث: قبل <strong id="wd-age">0</strong> ثوانٍ</p>
    <button class="btn btn-ghost btn-small" id="wd-pause" type="button">إيقاف مؤقت</button>
    <p class="muted small">صفحة الويب الحقيقية تتحدث تلقائيًا بـ <span dir="ltr">meta refresh</span> أو بجلب البيانات — هنا نحاكي النتيجة.</p></div>`;
  const tEl = slot.querySelector("#wd-t"), hEl = slot.querySelector("#wd-h"),
        ts = slot.querySelector("#wd-ts"), hs = slot.querySelector("#wd-hs"),
        tv = slot.querySelector("#wd-tv"), hv = slot.querySelector("#wd-hv"),
        auto = slot.querySelector("#wd-auto"), age = slot.querySelector("#wd-age"),
        pauseBtn = slot.querySelector("#wd-pause");
  let T = 26, H = 55, ageSec = 0, paused = false;
  function draw() {
    tEl.textContent = T.toFixed(1); hEl.textContent = Math.round(H);
    tv.textContent = ts.value; hv.textContent = hs.value; age.textContent = ageSec;
  }
  ts.addEventListener("input", () => { T = Number(ts.value); ageSec = 0; draw(); });
  hs.addEventListener("input", () => { H = Number(hs.value); ageSec = 0; draw(); });
  pauseBtn.addEventListener("click", () => { paused = !paused; pauseBtn.textContent = paused ? "استئناف" : "إيقاف مؤقت"; });
  expTimer(() => {
    if (paused) return;
    ageSec++;
    if (auto.checked && ageSec >= 2) {
      T = Math.max(15, Math.min(40, Number(ts.value) + (T - Number(ts.value)) * 0.5 + (Math.random() * 0.8 - 0.4)));
      H = Math.max(20, Math.min(90, Number(hs.value) + (H - Number(hs.value)) * 0.5 + (Math.random() * 2 - 1)));
      ageSec = 0;
    }
    draw();
  }, 1000);
  draw();
};

/* ===== 5-04: قناة IoT — إرسال القراءات ===== */
ACADEMY_EXPERIMENTS["iotchart"] = function (slot, exp) {
  slot.innerHTML = `<div class="exp-box">
    <div class="exp-controls">
      <label>الحرارة الأساسية: <strong id="io-v">25</strong> °C<input type="range" id="io-base" min="15" max="35" step="0.5" value="25"></label>
    </div>
    <div id="io-bars" style="display:flex;align-items:flex-end;gap:4px;height:110px;background:#f8fafc;border-radius:10px;padding:8px"></div>
    <div id="io-log" dir="ltr" style="background:#111827;color:#a7f3d0;font-family:monospace;font-size:12px;border-radius:8px;padding:8px 12px;margin-top:8px;min-height:38px;white-space:pre-line;text-align:left">channel empty</div>
    <div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center">
      <button class="btn btn-primary btn-small" id="io-send" type="button">أرسل قراءة الآن</button>
      <label><input type="checkbox" id="io-auto"> إرسال تلقائي كل 3 ثوانٍ</label>
    </div>
    <p class="muted small">منصات <span dir="ltr">IoT</span> تستقبل البيانات وتعرضها منحنيات. تنبيه: حدّ <span dir="ltr">ThingSpeak</span> المجاني هو تحديث واحد كل 15 ثانية للقناة — الإرسال الأسرع تختفي نقطه بصمت، وهنا نسرّع الزمن للعرض فقط.</p></div>`;
  const base = slot.querySelector("#io-base"), vEl = slot.querySelector("#io-v"),
        bars = slot.querySelector("#io-bars"), log = slot.querySelector("#io-log"),
        auto = slot.querySelector("#io-auto");
  const entries = [];
  function fmtTime(totalSec) {
    const h = String(Math.floor(totalSec / 3600)).padStart(2, "0"),
          m = String(Math.floor(totalSec % 3600 / 60)).padStart(2, "0"),
          s = String(totalSec % 60).padStart(2, "0");
    return h + ":" + m + ":" + s;
  }
  function send() {
    const id = entries.length + 1;
    const val = Math.round((Number(base.value) + (Math.random() * 1.6 - 0.8)) * 10) / 10;
    entries.push({ id, time: fmtTime(9 * 3600 + (id - 1) * 15), val });
    const last = entries.slice(-12);
    bars.innerHTML = last.map(e =>
      `<div title="${e.val}" style="flex:1;background:#0d9488;border-radius:4px 4px 0 0;height:${Math.round(e.val / 40 * 100)}%"></div>`).join("");
    log.textContent = entries.slice(-4).map(e => "#" + e.id + "  " + e.time + "  field1=" + e.val.toFixed(1)).join("\n");
  }
  base.addEventListener("input", () => { vEl.textContent = base.value; });
  slot.querySelector("#io-send").addEventListener("click", send);
  expTimer(() => { if (auto.checked) send(); }, 3000);
  send();
};

/* ===== 5-05: التحكم عبر BLE ===== */
ACADEMY_EXPERIMENTS["bleled"] = function (slot, exp) {
  slot.innerHTML = `<div class="exp-box">
    <p>حالة البلوتوث: <strong id="bl-status">غير متصل</strong></p>
    <div class="exp-led-wrap"><div class="exp-led" id="bl-led"></div><div class="exp-led-label">LED — GPIO2</div></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0">
      <button class="btn btn-primary btn-small" id="bl-scan" type="button">بحث عن أجهزة BLE</button>
      <button class="btn btn-ghost btn-small" id="bl-connect" type="button" hidden>اتصال بـ ESP32-LED</button>
      <button class="btn btn-ghost btn-small" id="bl-on" type="button" disabled>تشغيل</button>
      <button class="btn btn-ghost btn-small" id="bl-off" type="button" disabled>إطفاء</button>
      <button class="btn btn-ghost btn-small" id="bl-disc" type="button" hidden>قطع الاتصال</button>
    </div>
    <div id="bl-log" dir="ltr" style="background:#111827;color:#a7f3d0;font-family:monospace;font-size:13px;border-radius:8px;padding:8px 12px;min-height:38px;white-space:pre-line;text-align:left">characteristic log</div>
    <p class="muted small">البلوتوث قصير المدى (نحو 10 أمتار) ولا يحتاج شبكة <span dir="ltr">Wi-Fi</span> — الهاتف يكتب القيمة في الخاصية، ودالة الاستجابة في اللوحة تنفّذ الأمر فورًا.</p></div>`;
  const st = slot.querySelector("#bl-status"), led = slot.querySelector("#bl-led"), log = slot.querySelector("#bl-log"),
        scan = slot.querySelector("#bl-scan"), conn = slot.querySelector("#bl-connect"),
        on = slot.querySelector("#bl-on"), off = slot.querySelector("#bl-off"), disc = slot.querySelector("#bl-disc");
  let connected = false;
  scan.addEventListener("click", () => {
    st.textContent = "جارٍ البحث…";
    expTimeout(() => { st.textContent = "وُجد جهاز: ESP32-LED"; conn.hidden = false; }, 900);
  });
  conn.addEventListener("click", () => {
    connected = true;
    st.textContent = "متصل ✓"; conn.hidden = true; disc.hidden = false;
    on.disabled = false; off.disabled = false;
    log.textContent = "connected to ESP32-LED\nservice + characteristic found";
  });
  function write(v) {
    if (!connected) return;
    led.classList.toggle("on", v === 1);
    log.textContent += "\n>> write value: " + v;
  }
  on.addEventListener("click", () => write(1));
  off.addEventListener("click", () => write(0));
  disc.addEventListener("click", () => {
    connected = false;
    st.textContent = "غير متصل"; disc.hidden = true;
    on.disabled = true; off.disabled = true;
    led.classList.remove("on");
    log.textContent = "characteristic log";
  });
};

